mapper.update:
UPDATE creator_profile
SET status = 'ACTIVE', version = version + 1, updated_at = CURRENT_TIMESTAMP(6)
WHERE user_id = #{userId}
  AND version = #{expectedVersion}
  AND status = 'DRAFT'

mapper.select:
SELECT EXISTS (
    SELECT 1 FROM creator_profile WHERE avatar_asset_id = #{assetId} LIMIT 1
) OR EXISTS (
    SELECT 1 FROM creator_profile WHERE banner_asset_id = #{assetId} LIMIT 1
)
